package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.domain.query.finance.ReconciliationQuery;import com.punjab.oms.ar.enums.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-reconciliation：限定独立客户fixture，不更改业务库。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.reconciliation.real",matches="true") @EnabledIfSystemProperty(named="ar.reconciliation.real.commit",matches="true")
class ReconciliationRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired ReconciliationService reconciliation;@Autowired ReceivableService create;@Autowired ReceiptService receipts;@Autowired SettlementService settlements;@Autowired JdbcTemplate jdbc;long customer;
 String key(){return UUID.randomUUID().toString();}BigDecimal n(String x){return new BigDecimal(x);}
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");try(var paths=Files.list(Path.of("../scratch/dbddl"))){for(var path:paths.filter(p->p.getFileName().toString().matches("V\\d+__.*\\.sql")).sorted().toList())for(String sql:Files.readString(path).split(";"))if(!sql.isBlank())jdbc.execute(sql);}customer=(UUID.randomUUID().getMostSignificantBits() & Long.MAX_VALUE)+1;CurrentUser.set(new CurrentUser.Identity("reconcile-test",Set.of(1L),Set.of("ar:create","ar:read","ar:receipt:create","ar:settle","ar:reverse","ar:balance:transfer","ar:invoice:write")));}
 @AfterEach void clear(){CurrentUser.clear();}
 ReconciliationQuery query(){var q=new ReconciliationQuery();q.setLegalEntityId(1L);q.setCustomerId(customer);q.setCurrency("CNY");return q;}
 long line(){long doc=create.create(new ReceivableCreateRequest(key(),customer,1L,"CNY","SERVICE",LocalDate.now(),null,"test",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,n("100"),null,null,null))));return jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);}
 @Test @DisplayName("正常创建核销及反核销无余额差异")void clean(){long id=line(),receipt=receipts.create(new ReceiptCreateRequest(key(),customer,1L,"CNY",n("100"),LocalDate.now(),"TEST",key(),"test"));long group=jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,id);var p=new SettlementPreviewRequest(1L,receipt,n("20"),List.of(group),AllocationStrategy.GROUP_TAX_FIRST);long settlement=settlements.confirm(new SettlementConfirmRequest(key(),p,settlements.preview(p).fingerprint(),"test"));assertThat(reconciliation.page(query()).total()).isZero();settlements.reverse(new SettlementReverseRequest(key(),1L,settlement,"undo"));assertThat(reconciliation.page(query()).total()).isZero();}
 @Test @DisplayName("已开票投影与有效分配不符报告实际对象且不修账")void invoiceMismatch(){long id=line();jdbc.update("UPDATE oms_ar_line SET invoiced_amount=7 WHERE id=?",id);var report=reconciliation.page(query());var d=report.records().stream().filter(r->r.rule().equals("LINE_INVOICED")).findFirst().orElseThrow();assertThat(d.rule()).isEqualTo("LINE_INVOICED");assertThat(d.objectId()).isEqualTo(id);assertThat(d.storedAmount()).isEqualByComparingTo("7");assertThat(d.expectedAmount()).isEqualByComparingTo("0");assertThat(jdbc.queryForObject("SELECT invoiced_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,id)).isEqualByComparingTo("7");}
 @Test @DisplayName("已核销及收款投影分别与分配核对")void storedMismatch(){long id=line();jdbc.update("UPDATE oms_ar_line SET settled_amount=10,open_amount=90 WHERE id=?",id);long receipt=receipts.create(new ReceiptCreateRequest(key(),customer,1L,"CNY",n("100"),LocalDate.now(),"TEST",key(),"test"));jdbc.update("UPDATE oms_ar_receipt SET allocated_amount=10 WHERE id=?",receipt);var result=reconciliation.page(query());assertThat(result.total()).isGreaterThanOrEqualTo(2);assertThat(result.records()).extracting(r->r.rule()).contains("LINE_SETTLED","RECEIPT_ALLOCATED");var q=query();q.setSize(1);assertThat(reconciliation.page(q).records()).hasSize(1);q.setPage(Integer.MAX_VALUE);assertThat(reconciliation.page(q).records()).isEmpty();}
 @Test @DisplayName("拒绝越权和缺失结算范围")void permission(){var q=query();q.setLegalEntityId(2L);assertThatThrownBy(()->reconciliation.page(q)).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);var missing=query();missing.setCustomerId(null);assertThatThrownBy(()->reconciliation.page(missing)).isInstanceOf(ServiceException.class);}
 @Autowired CustomerBalanceService balances;@Autowired BalanceSettlementService spend;@Autowired InvoiceService invoices;
 @Test @DisplayName("账户批次和余额分配正常时无差异，损坏后逐项定位")void balanceRules(){
  long positive=line();long doc=create.create(new ReceivableCreateRequest(key(),customer,1L,"CNY","SERVICE",LocalDate.now(),null,"credit",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,n("-100"),null,null,null))));
  long negative=jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);long lot=balances.transfer(new BalanceTransferRequest(key(),1L,negative,n("40"),0L,"transfer"));long account=jdbc.queryForObject("SELECT account_id FROM oms_ar_balance_lot WHERE id=?",Long.class,lot);long group=jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,positive);
  var preview=new BalanceSettlementPreviewRequest(1L,account,n("10"),List.of(group),AllocationStrategy.GROUP_TAX_FIRST);long settlement=spend.confirm(new BalanceSettlementConfirmRequest(key(),preview,spend.preview(preview).fingerprint(),"spend"));assertThat(reconciliation.page(query()).total()).isZero();
  jdbc.update("UPDATE oms_ar_customer_account SET balance_amount=29 WHERE id=?",account);
  jdbc.update("UPDATE oms_ar_line SET transferred_amount=-39,open_amount=-61 WHERE id=?",negative);
  jdbc.update("UPDATE oms_ar_balance_usage SET amount=9 WHERE settlement_id=?",settlement);
  jdbc.update("UPDATE oms_ar_settlement SET amount=9 WHERE id=?",settlement);
  var report=reconciliation.page(query());assertThat(report.records()).extracting(r->r.rule()).contains("ACCOUNT_BALANCE","LINE_TRANSFERRED","LOT_USED","SETTLEMENT_TOTAL","BALANCE_ALLOCATION_USAGE");
  var other=query();other.setCurrency("USD");assertThat(reconciliation.page(other).total()).isZero();other.setCurrency("CNY");other.setCustomerId(customer+1);assertThat(reconciliation.page(other).total()).isZero();
 }
 @Test @DisplayName("有效开票分配及撤销均与投影一致")void invoiceClean(){long id=line();var preview=new InvoicePreviewRequest(1L,customer,"CNY",InvoiceKind.BLUE,null,n("10"),List.of(new InvoicePreviewRequest.Line("1",id,n("10"),null,null)));long invoice=invoices.register(new InvoiceRegisterRequest(key(),"TEST",key(),key(),LocalDate.now(),preview,invoices.preview(preview).fingerprint(),"invoice"));assertThat(reconciliation.page(query()).total()).isZero();invoices.reverse(new InvoiceReverseRequest(key(),1L,invoice,"undo"));assertThat(reconciliation.page(query()).total()).isZero();}

 long negative(){long doc=create.create(new ReceivableCreateRequest(key(),customer,1L,"CNY","SERVICE",LocalDate.now(),null,"credit",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,n("-100"),null,null,null))));return jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);}
 long invoice(InvoicePreviewRequest preview){return invoices.register(new InvoiceRegisterRequest(key(),"TEST",key(),key(),LocalDate.now(),preview,invoices.preview(preview).fingerprint(),"invoice"));}
 @Test @DisplayName("发票单头与明细合计不同会报告")void invoiceTotal(){long id=line();long inv=invoice(new InvoicePreviewRequest(1L,customer,"CNY",InvoiceKind.BLUE,null,n("10"),List.of(new InvoicePreviewRequest.Line("1",id,n("10"),null,null))));jdbc.update("UPDATE oms_ar_invoice SET total_amount=9 WHERE id=?",inv);assertThat(reconciliation.page(query()).records()).anyMatch(d->d.rule().equals("INVOICE_TOTAL") && d.objectId().equals(inv) && d.expectedAmount().compareTo(n("10"))==0);}
 @Test @DisplayName("红字超过原分配即使投影金额一致也需报告")void redLimit(){long id=line();long blue=invoice(new InvoicePreviewRequest(1L,customer,"CNY",InvoiceKind.BLUE,null,n("10"),List.of(new InvoicePreviewRequest.Line("1",id,n("10"),null,null))));long original=jdbc.queryForObject("SELECT id FROM oms_ar_invoice_allocation WHERE invoice_id=?",Long.class,blue);long credit=negative();long red=invoice(new InvoicePreviewRequest(1L,customer,"CNY",InvoiceKind.RED,blue,n("-5"),List.of(new InvoicePreviewRequest.Line("1",credit,n("-5"),null,original))));assertThat(reconciliation.page(query()).total()).isZero();jdbc.update("UPDATE oms_ar_invoice_allocation SET amount=-11 WHERE invoice_id=?",red);jdbc.update("UPDATE oms_ar_invoice SET total_amount=-11 WHERE id=?",red);jdbc.update("UPDATE oms_ar_line SET invoiced_amount=-11 WHERE id=?",credit);assertThat(reconciliation.page(query()).records()).anyMatch(d->d.rule().equals("INVOICE_RED_EXCESS") && d.objectId().equals(original) && d.storedAmount().compareTo(n("11"))==0 && d.expectedAmount().compareTo(n("10"))==0);}
 @Autowired OffsetService offsets;
 @Test @DisplayName("负数抵销及反核销不产生符号误报")void offsetClean(){long positive=line(),credit=negative(),group=jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,positive);var p=new OffsetPreviewRequest(1L,credit,n("20"),List.of(group),false,AllocationStrategy.GROUP_TAX_FIRST);long settlement=offsets.confirm(new OffsetConfirmRequest(key(),p,offsets.preview(p).fingerprint(),"offset"));assertThat(reconciliation.page(query()).total()).isZero();settlements.reverse(new SettlementReverseRequest(key(),1L,settlement,"undo"));assertThat(reconciliation.page(query()).total()).isZero();}
 @Test @DisplayName("余额反核销保留历史分配且当前批次使用归零")void balanceReverseClean(){long positive=line(),credit=negative(),lot=balances.transfer(new BalanceTransferRequest(key(),1L,credit,n("40"),0L,"transfer")),account=jdbc.queryForObject("SELECT account_id FROM oms_ar_balance_lot WHERE id=?",Long.class,lot),group=jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,positive);var p=new BalanceSettlementPreviewRequest(1L,account,n("10"),List.of(group),AllocationStrategy.GROUP_TAX_FIRST);long settlement=spend.confirm(new BalanceSettlementConfirmRequest(key(),p,spend.preview(p).fingerprint(),"spend"));settlements.reverse(new SettlementReverseRequest(key(),1L,settlement,"undo"));assertThat(reconciliation.page(query()).total()).isZero();balances.reverseTransfer(new BalanceTransferReverseRequest(key(),1L,lot,"undo transfer"));assertThat(reconciliation.page(query()).total()).isZero();}

 @Test @DisplayName("原始金额不变但版本或税率绕过流水修改会报告末次快照差异")void auditLatest(){long id=line();jdbc.update("UPDATE oms_ar_line SET version=version+1,tax_rate=0.09 WHERE id=?",id);assertThat(reconciliation.page(query()).records()).anyMatch(d->d.rule().equals("LINE_AUDIT_LATEST") && d.objectId().equals(id));}
 @Test @DisplayName("初始化快照被隐藏后报告缺失，不能因金额相等放过")void auditInitial(){long id=line();jdbc.update("UPDATE oms_ar_lifecycle_change SET delete_status=true WHERE object_type='LINE' AND object_id=? AND before_version IS NULL",id);assertThat(reconciliation.page(query()).records()).anyMatch(d->d.rule().equals("LINE_AUDIT_INITIAL") && d.objectId().equals(id));}

 @Test @DisplayName("历史坏数据的余额公式与作废占用均可诊断")void invalidBalances(){long active=line(),invalidVoid=line();jdbc.execute("ALTER TABLE oms_ar_line ALTER CHECK ck_line_balance NOT ENFORCED");try{jdbc.update("UPDATE oms_ar_line SET open_amount=99 WHERE id=?",active);jdbc.update("UPDATE oms_ar_line SET status='VOID',open_amount=0,invoiced_amount=1 WHERE id=?",invalidVoid);var report=reconciliation.page(query());assertThat(report.records()).anyMatch(d->d.rule().equals("LINE_OPEN") && d.objectId().equals(active));assertThat(report.records()).anyMatch(d->d.rule().equals("LINE_VOID_OCCUPANCY") && d.objectId().equals(invalidVoid));}finally{jdbc.update("UPDATE oms_ar_line SET status='ACTIVE',open_amount=100,invoiced_amount=0 WHERE id IN (?,?)",active,invalidVoid);jdbc.execute("ALTER TABLE oms_ar_line ALTER CHECK ck_line_balance ENFORCED");}}

}
